mapper.select:
select uvr.id, uvr.user_id, uvr.voc_id, uvr.review_interval, uvr.type
from voc_chap_book vcb inner join user_voc_rev uvr on vcb.book_id=#{bookId} and uvr.user_id=#{userId}
     and vcb.voc_id = uvr.voc_id

select count(*) as count
from voc_chap_book vcb inner join user_voc_rev uvr on vcb.book_id=#{bookId} and uvr.user_id=#{userId}
    and vcb.voc_id = uvr.voc_id
group by uvr.type
having uvr.type = #{type}

select count(*)
from voc_chap_book vcb inner join user_voc_rev uvr on vcb.book_id=#{bookId} and uvr.user_id=#{userId}
    and vcb.voc_id = uvr.voc_id


        where uvr.review_interval >= #{interval}


        where uvr.review_interval = #{interval}


and uvr.type = 1
